"use strict";(self.webpackChunkmy_site=self.webpackChunkmy_site||[]).push([["5568"],{724(e){e.exports=JSON.parse('{"tag":{"label":"Differential Geometry","permalink":"/docs/tags/differential-geometry","allTagsPath":"/docs/tags","count":1,"items":[{"id":"differential-geometry","title":"Differential Geometry and Fibre Bundle for Babies","description":"It is well known that textbooks, notes, and lecture materials in mathematics and physics have a long-standing tradition of deliberately presenting content in an obscure and difficult-to-understand manner. This practice\u2014erasing the traces of thought processes while leaving only elegant results\u2014has created a deep and formidable barrier between beginners and mathematical knowledge. This became especially evident to me when I attempted to self-study differential geometry, general relativity, fiber bundles, and gauge theory.","permalink":"/docs/differential-geometry"}],"unlisted":false}}')}}]);